import std.io

pub type AppError = Failed(String)

fn bump(n: Int64) -> Int64 {
    n = n + 10
    return n
}

fn parityClass(n: Int64) -> Int64 {
    while n >= 2 {
        n = n - 2
    }
    return n
}

pub fn main() effect io -> Result<(), AppError> {
    let b = bump(5)
    if b == 15 { io.println("bump-ok") } else { io.println("bump-bad") }
    let p = parityClass(9)
    if p == 1 { io.println("loop-ok") } else { io.println("loop-bad") }
    return Ok(())
}
